fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Handle the case of an empty array
    if a.is_empty() {
        return (Vec::new(), Vec::new());
    }
    
    // Handle the case of a single element array
    if a.len() == 1 {
        return (Vec::new(), a);
    }
    
    // Split the array into two parts
    let first_part = vec![a[0]]; // Take the first element
    let second_part = a[1..].to_vec(); // Take the rest of the elements
    
    (first_part, second_part)
}